-- Añade las representaciones diplomáticas de países hispanohablantes en Londres.
-- Los datos de contacto y sedes se consultan en el listado oficial británico, que se actualiza periódicamente.
-- Puerto Rico no se incluye como embajada independiente: es un territorio de Estados Unidos y sus asuntos consulares corresponden a la representación estadounidense.
-- Ejecutar en Supabase SQL Editor.

on conflict (slug) do update set
  name=excluded.name,
  category=excluded.category,
  listing_type=excluded.listing_type,
  description=excluded.description,
  city=excluded.city,
  website=excluded.website,
  opening_hours=excluded.opening_hours,
  status='published',
  sponsored=false,
  verified_at=now(),
  updated_at=now();
